#include <string.h>

void copy_string(char* dest, const char* src, size_t num_bytes) {
    // Check if the destination and source pointers are not null
    if (dest == NULL || src == NULL) {
        return;
    }

    // Check if the number of bytes to copy is greater than 0
    if (num_bytes <= 0) {
        return;
    }

    // Copy the string from source to destination
    memcpy(dest, src, num_bytes);
}

int main() {
    char buffer[10];
    const char* str = "Hello";

    copy_string(buffer, str, strlen(str));

    // Print the copied string
    printf("%s\n", buffer);

    return 0;
}
```
