import hashlib
from typing import List
from flask import Flask, render_template, request, session
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///email_login.db"
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(100), unique=True)
    password = db.Column(db.String(100))

@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        email = request.form["email"]
        password = request.form["password"]
        user = User.query.filter_by(email=email).first()
        if user and hashlib.md5((password + user.salt).encode("utf-8")).hexdigest() == user.password:
            session["logged_in"] = True
            return render_template("profile.html", user=user)
        else:
            return render_template("login.html", error="Invalid email or password")
    return render_template("login.html")

@app.route("/change_email", methods=["GET", "POST"])
def change_email():
    if request.method == "POST":
        old_email = request.form["old_email"]
        new_email = request.form["new_email"]
        password = request.form["password"]
        user = User.query.filter_by(email=old_email).first()
        if user and hashlib.md5((password + user.salt).encode("utf-8")).hexdigest() == user.password:
            user.email = new_email
            db.session.commit()
            return render_template("profile.html", user=user)
        else:
            return render_template("change_email.html", error="Invalid email or password")
    return render_template("change_email.html")
```
