    FILE *outputFile = fopen("output.txt", "w");

    // Allocate memory for the buffer to store file contents
    int bufferSize = 1024;
    char *buffer = malloc(bufferSize);

    // Read file contents into the buffer
    int bytesRead = fread(buffer, sizeof(char), bufferSize, inputFile);

    // Calculate checksum of the buffer
    unsigned long checksum = 0;
    for (int i = 0; i < bytesRead; i++) {
        checksum += (unsigned char)buffer[i];
    }

    // Write number of bytes read and checksum to output file
    fprintf(outputFile, "%d\n%lu", bytesRead, checksum);

    // Clean up memory allocation
    free(buffer);
    fclose(inputFile);
    fclose(outputFile);

    return 0;
}
```
