int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <string>\n", argv[0]);
        return 1;
    }

    char* input_str = argv[1];
    size_t len = strlen(input_str);

    // Trim trailing whitespace
    while (len > 0 && isspace((unsigned char)input_str[len - 1])) {
        input_str[len - 1] = '\0';
        len--;
    }

    // Trim newlines
    for (size_t i = 0; i < len; i++) {
        if (input_str[i] == '\n') {
            memmove(input_str + i, input_str + i + 1, len - i);
            len--;
            i--;
        }
    }

    // Null-terminate the string
    input_str[len] = '\0';

    return 0;
}
```
