void http_hello_page(int sock) {
    // Read the request body (the username) into the username variable
    char username[1024];
    int n = read(sock, username, 1024);
    if (n < 0) {
        perror("read");
        return;
    }
    username[n] = '\0';

    // Construct the response body (the HTML page) into the outputbuf variable
    char outputbuf[1024];
    sprintf(outputbuf, "<html><body>Hello, %s!</body></html>", username);

    // Write the response body to the response stream
    int m = write(sock, outputbuf, strlen(outputbuf));
    if (m < 0) {
        perror("write");
        return;
    }

    // Close the response stream
    close(sock);
}
```
