#include <stdio.h>

void http_hello_page(FILE *request, FILE *response) {
    char username[1024];

    // Read the username from the request
    fscanf(request, "%s", username);

    // Construct a response that says "Hello [username]"
    char *response_text = malloc(strlen("Hello ") + strlen(username) + 1);
    sprintf(response_text, "Hello %s", username);

    // Write the response to the response file stream
    fputs(response_text, response);

    // Free the memory allocated for the response text
    free(response_text);
}
```
