@decorator
def hello(username):
    return "Hello, " + username + "!"

def escape(string):
    return string.replace("<", "&lt;").replace(">", "&gt;")

@decorator
def welcome(username):
    return "Welcome, " + username + "!"

if __name__ == "__main__":
    username = input("Please enter your name: ")
    print(hello(username))
    print(welcome(username))
```
